  "        { type:'configure', payloadSchema:{ type:'object', properties:{ difficulty:{ type:'string', enum:['easy','normal','hard'] } }, required:['difficulty'], additionalProperties:false } },",
  "        { type:'start' }",
  "      ];",
  "    }",
