  "      {type:'pause'}",
  "    ];",
  "  },",
  "  reduce(context, action) {",
  "    var s=context.state;",
  "    if (!s.started) {",
  "      if (action.type==='configure') {",
  "        var d=action.payload&&action.payload.difficulty;",
