  "      var cap={x:s.capsules[ci].x,y:s.capsules[ci].y+0.22*sec,type:s.capsules[ci].type};",
  "      if (cap.y>=PADDLE_Y-0.02 && cap.y<=PADDLE_Y+0.045 && Math.abs(cap.x-s.px)<=half+0.025) {",
  "        if (cap.type==='wide') wide=10000;",
