  "        else if (cap.type==='fire') fire=10000;",
  "        else if (cap.type==='laser') { laser=10000; laserCooldown=0; }",
  "        else if (cap.type==='score') scoreBoost=10000;",
  "      } else if (cap.y<1.05) capsules.push(cap);",
  "    }",
  "    // Laser periodically damages the lowest surviving brick above the paddle.",
